import heapq


def bestItems(items, c, k):
    groups = {}
    for g, v in items:
        if v <= 0:
            continue
        h = groups.setdefault(g, [])
        if len(h) < c:
            heapq.heappush(h, v)
        else:
            heapq.heappushpop(h, v)
    pool = [v for h in groups.values() for v in h]
    return sum(heapq.nlargest(k, pool))
